with base as (select id, session_id, event_type, page, event_time, duration_sec, round(duration_sec, 1) as duration_sec_rounded, case when event_type in ('purchase', 'search') then 'Tier 1' else 'Other' end as event_type_group from web_events where page is not null and page in ('/search', '/checkout')) select a.*, s.country, s.browser from base a left join sessions s on a.session_id = s.id
